from pathlib import Path
import importlib.util,json,os,statistics,sys
sys.dont_write_bytecode=True
root=Path(__file__).resolve().parent;identity=json.loads((root/'identity.json').read_text());source=Path(identity['source_root']);project=Path(identity['project'])
s=importlib.util.spec_from_file_location('cost',source/'docs/architecture/jsdoc-cost-controls.py');cost=importlib.util.module_from_spec(s);s.loader.exec_module(cost)
for k in list(os.environ):
 if k.startswith('TSR_'):os.environ.pop(k)
base=json.loads((root/'baseline-phase.json').read_text());cost.require(base['complete'],'incomplete baseline build/corpus')
binaries={'baseline':Path(base['binaries']['cli']['path'])}
candidate=root/'candidate-binaries/tsr'
paired=candidate.exists()
if paired:binaries['candidate']=candidate
out=root/('pairs' if paired else 'normal-baseline');out.mkdir(exist_ok=False)
flags=['--project',str(project),'--noEmit','--incremental','false','--composite','false','--pretty','false']
state={'source':identity['source'],'candidate_patch':json.loads((root/'candidate-identity.json').read_text()) if paired else None,'driver_sha256':cost.file_hash(Path(__file__)),'binary_sha256':{k:cost.file_hash(v) for k,v in binaries.items()},'flags':flags,'preflights':[],'samples':[],'rounds':[],'complete':False,'complete_input_equivalence_verified':False,'native_target_verified':False,'actual_default_worker_evidence':'unavailable in ordinary binaries; source pool/eligibility unchanged; separate trace forces single worker and cannot prove default admission'}
result=out/'results.json'
def save():cost.write(result,state)
def child(role,mode,label,extra,trace=False):
 cost.require(all(cost.file_hash(b)==state['binary_sha256'][r] for r,b in binaries.items()),'binary changed')
 c=cost.process([str(binaries[role]),*flags,*([] if mode=='default' else ['--singleThreaded']),*extra],project.parent,180)
 paths={stream:out/(label+'.'+stream) for stream in ('stdout','stderr')}
 for stream,p in paths.items():p.write_text(c[stream])
 record={k:v for k,v in c.items() if k not in ('stdout','stderr')};record.update(role=role,mode=mode,raw={stream:{'path':str(p),'sha256':cost.file_hash(p)} for stream,p in paths.items()})
 return c,record
save()
loaded=None
for role in binaries:
 c,r=child(role,'default',role+'-listing',['--listFilesOnly']);state['preflights'].append(r);save();cost.require(c['exit_code']==0 and not c['timed_out'],'listing incomplete')
 names=cost.files(c);cost.require(names,'empty listing')
 if loaded is None:loaded=names
 cost.require(names==loaded,'loaded order differs')
known_root=Path(Path('/tmp/tsr-cost-refresh-path').read_text().strip());known=json.loads((known_root/'inputs.json').read_text())['paths']
libroot=(source/'vendor/typescript-go/internal/bundled/libs').resolve()
def physical(name):
 if name.startswith('bundled:///libs/'):
  leaf=name.removeprefix('bundled:///libs/');cost.require('/' not in leaf and leaf.startswith('lib.') and leaf.endswith('.d.ts'),'unexpected bundled library');return str(libroot/leaf)
 cost.require(name.startswith('/'),'relative loaded identity');return name
paths=sorted(set(known+[str(project)]+[physical(name) for name in loaded]))
observed=cost.snapshot(paths);cost.require(cost.valid_snapshot(observed),'invalid observed inputs');cost.write(out/'inputs.json',observed)
state.update(loaded_count=len(loaded),ordered_loaded_fingerprint=cost.fingerprint(loaded),input_fingerprint=cost.fingerprint(observed),input_receipt={'path':str(out/'inputs.json'),'sha256':cost.file_hash(out/'inputs.json')},input_coverage='prior caller-supplied observed query paths plus current loaded/config/library bytes; partial, excluding unobserved queries and transient changes')
configs={}
for mode in ('default','single'):
 for role in binaries:
  c,r=child(role,mode,role+'-'+mode+'-config',['--showConfig']);state['preflights'].append(r);save();cost.require(c['exit_code']==0 and not c['timed_out'],'showConfig incomplete')
  configs[(role,mode)]=json.loads(c['stdout'])
 if paired:cost.require(configs[('baseline',mode)]==configs[('candidate',mode)],'effective options differ')
state['config_fingerprints']={r+'-'+m:cost.fingerprint(c) for (r,m),c in configs.items()};save()
expected=None
for role in binaries:
 for mode in ('default','single'):
  cost.require(cost.snapshot(paths)==observed,'preflight inputs changed')
  c,r=child(role,mode,role+'-'+mode+'-warmup',['--listFiles','--extendedDiagnostics'])
  signature={'diagnostics':cost.diagnostics(c['stdout']+c['stderr'],project.parent),'counts':cost.counts(c),'loaded_fingerprint':cost.fingerprint(cost.files(c)),'exit_code':c['exit_code']}
  r['signature']=signature;state['preflights'].append(r);save();cost.require(c['exit_code'] in (0,1,2) and not c['timed_out'],'warmup failed');cost.require(cost.files(c)==loaded,'warmup loaded order changed')
  if expected is None:expected=signature
  cost.require(signature==expected,'warmup changes diagnostics/reported scope');cost.require(cost.snapshot(paths)==observed,'warmup inputs changed')
state['expected_output']=expected;save()
for round_index in range(2):
 record={'round':round_index+1,'modes':{}};state['rounds'].append(record);save()
 for mode in (('default','single') if round_index==0 else ('single','default')):
  rows=[]
  for pair in range(5 if paired else 1):
   order=('baseline','candidate') if (pair+round_index)%2==0 else ('candidate','baseline')
   for role in order if paired else ('baseline',):
    cost.require(cost.snapshot(paths)==observed,'inputs changed before timed child')
    c,r=child(role,mode,f'{round_index+1}-{mode}-{pair}-{role}',['--listFiles','--extendedDiagnostics'])
    signature={'diagnostics':cost.diagnostics(c['stdout']+c['stderr'],project.parent),'counts':cost.counts(c),'loaded_fingerprint':cost.fingerprint(cost.files(c)),'exit_code':c['exit_code']}
    r.update(round=round_index+1,pair=pair,signature=signature);state['samples'].append(r);rows.append(r);save()
    cost.require(not c['timed_out'] and c['exit_code'] in (0,1,2),'timed child incomplete');cost.require(signature==expected and cost.files(c)==loaded,'timed child changes full output/reported scope');cost.require(cost.snapshot(paths)==observed,'inputs changed after timed child')
    print(json.dumps({'round':round_index+1,'mode':mode,'pair':pair,'role':role,'wall':c['wall_seconds']}),flush=True)
  medians={role:{metric:statistics.median(c[metric] for c in rows if c['role']==role) for metric in ('wall_seconds','user_seconds','system_seconds','peak_rss_bytes')} for role in binaries}
  detail={'medians':medians,'ranges':{role:{metric:[min(c[metric] for c in rows if c['role']==role),max(c[metric] for c in rows if c['role']==role)] for metric in ('wall_seconds','user_seconds','system_seconds','peak_rss_bytes')} for role in binaries}}
  if paired:detail.update(saved_wall_seconds=medians['baseline']['wall_seconds']-medians['candidate']['wall_seconds'],peak_rss_ratio=medians['candidate']['peak_rss_bytes']/medians['baseline']['peak_rss_bytes'])
  record['modes'][mode]=detail;save()
  print('SUMMARY',round_index+1,mode,json.dumps(detail),flush=True)
state['distinct_sample_pids']=len({c['pid'] for c in state['samples']})==len(state['samples']);cost.require(state['distinct_sample_pids'],'sample PID reused')
cost.require(cost.snapshot(paths)==observed,'final inputs changed');state['complete']=True;save()
role='candidate' if paired else 'baseline';summary={mode:{metric:statistics.median(c[metric] for c in state['samples'] if c['mode']==mode and c['role']==role) for metric in ('wall_seconds','user_seconds','system_seconds','peak_rss_bytes')} for mode in ('default','single')}
metrics={'wall_seconds':summary['default']['wall_seconds'],'single_wall_seconds':summary['single']['wall_seconds'],'complete_process':1,'outputs_preserved':1,'observed_inputs_stable':1,'full_corpus_preserved':int(json.loads((root/'corpus-comparison.json').read_text())['previous_right_losses']==0) if paired else 1,'memory_policy_pass':int(all(m['peak_rss_ratio']<=1.05 for r in state['rounds'] for m in r['modes'].values())) if paired else 1,**{k:summary['default'][k] for k in ('user_seconds','system_seconds','peak_rss_bytes')}}
cost.write(out/'metrics.json',metrics);print(json.dumps(metrics),flush=True)
